public import CoreKit
public import Foundation
public import Hummingbird

/// One route with its OpenAPI metadata, generated by `@GET`, `@POST`, ...
public struct Endpoint: Sendable {
    public enum Method: String, Sendable {
        case get, post, put, patch, delete
    }

    public enum ResponseKind {
        /// 200 with the JSON-encoded result.
        case json(any SchemaRepresentable.Type)
        /// 204 for handlers returning `Void`.
        case noContent
        /// A handler-built `Response`, documented without a body schema.
        case raw
    }

    public struct PathParameter: Sendable {
        let name: String
        let schema: JSONSchema

        public init<Value: SchemaRepresentable & LosslessStringConvertible>(_ name: String, _ type: Value.Type) {
            self.name = name
            self.schema = Value.jsonSchema
        }

        public init(_ name: String, _ type: UUID.Type) {
            self.name = name
            self.schema = UUID.jsonSchema
        }
    }

    let method: Method
    /// Whether the route answers `HEAD` as well, like its `GET` without the body.
    let answersHead: Bool
    /// Relative to the router until mounted by `OpenAPIDocument`.
    var path: String
    var tag: OpenAPITag?
    let operationID: String
    let summary: String?
    let pathParameters: [PathParameter]
    let querySchema: JSONSchema?
    let requestBody: (contentType: String, schema: JSONSchema)?
    let securitySchemes: [OpenAPISecurityScheme]
    /// `nil` for `.noContent` and `.raw`.
    let responseSchema: JSONSchema?
    let responseStatus: Int
    let handler: @Sendable (Request, BasicRequestContext) async throws -> Response

    public init(
        method: Method,
        head: Bool = false,
        path: String,
        operationID: String,
        summary: String?,
        pathParameters: [PathParameter],
        query: (any SchemaRepresentable.Type)?,
        body: (any SchemaRepresentable.Type)?,
        form: (any SchemaRepresentable.Type)? = nil,
        security: [OpenAPISecurityScheme?],
        response: ResponseKind,
        handler: @escaping @Sendable (Request, BasicRequestContext) async throws -> Response
    ) {
        self.method = method
        self.answersHead = head
        self.path = path
        self.operationID = operationID
        self.summary = summary
        self.pathParameters = pathParameters
        self.querySchema = query?.jsonSchema
        self.requestBody =
            if let body {
                ("application/json", body.jsonSchema)
            } else if let form {
                ("multipart/form-data", form.jsonSchema)
            } else {
                nil
            }
        self.securitySchemes = security.compactMap(\.self)
        switch response {
        case .json(let type): (responseSchema, responseStatus) = (type.jsonSchema, 200)
        case .noContent: (responseSchema, responseStatus) = (nil, 204)
        case .raw: (responseSchema, responseStatus) = (nil, 200)
        }
        self.handler = handler
    }
}
